WITH valid AS (SELECT id, device_code, reading_ts, humidity, pressure, firmware, CAST(status_bits AS DOUBLE) AS status_bits_str FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 06:00:00'), with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM valid), gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 1 HOUR THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT session_id, (UNIX_TIMESTAMP(MAX(prev_reading_ts)) - UNIX_TIMESTAMP(MIN(prev_reading_ts))) / 60 AS span_minutes, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count FROM sessions_device_readings GROUP BY session_id
